import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {projectOptions} from '../src/project.mjs';import {BUILD_INFO} from '../config/build-info.mjs';import {createFacadePackage} from '../src/model.mjs';import {bindDesignSession,bindStudioEditor} from '../integration/site-bindings.mjs';import {closeupPlan} from '../src/comparison.mjs';import {copy} from '../src/core.mjs';
const json=p=>JSON.parse(fs.readFileSync(new URL(p,import.meta.url))),policy=json('../config/project-policy.json'),doc=json('../examples/source-C1.json'),built=json('../examples/source-built.json'),transforms=json('../examples/source-transforms.json');
const resolve=(p=policy,b=BUILD_INFO)=>projectOptions({policy:p,buildInfo:b,projectId:'project-1',designId:'design-1'});
test('real pinned baseline replaces placeholder, identities remain distinct',()=>{const r=resolve();assert.equal(r.sourceRevision,'2bbe9afc189161e8c845dee9944298411189e9f9');assert.equal(r.projectEvidence.identity.packageName,'@mizan/facade-kit');assert.equal(r.projectEvidence.identity.projectName,'MIZAN-ALHANDASAH');assert.throws(()=>resolve(policy,{...BUILD_INFO,sourceRevision:'REPLACE_WITH_TESTED_SITE_COMMIT'}),/REAL_SOURCE_REVISION/);});
test('unverified projections cannot silently use the 0.7m example',()=>{const p=copy(policy);p.projection.maxProjectionM.s=.7;assert.throws(()=>resolve(p),/UNVERIFIED_PROJECTION_NOT_ZERO/);});
test('zero policy disables new proposals without breaking generation',async()=>{const p=await createFacadePackage(built,{...resolve(),transforms,style:'B'});assert.ok(p.issues.some(i=>i.code==='NEW_PROJECTIONS_DISABLED'));assert.equal(p.built.s.layers.filter(l=>l.id.includes(':kit:')).length,0);assert.equal(p.projectEvidence.stone.status,'VISUAL_ASSUMPTION');});
test('project usage requires project and product evidence',()=>{const p=copy(policy);p.usage='project';assert.throws(()=>resolve(p),/PROJECT_POLICY_INCOMPLETE/);p.projection.status='PROJECT_REVIEWED';p.stone.status='PRODUCT_DEFINED';assert.throws(()=>resolve(p),/STONE_PRODUCT_REFERENCE/);p.stone.productId='manufacturer-product';p.stone.technicalDocument='project/doc-001';assert.equal(resolve(p).projectEvidence.usage,'project');});
test('design-session binding follows active alternative, including identical documents',async()=>{const session={createdAt:100,current:0,designs:[{version:1,doc:JSON.stringify(doc)},{version:2,doc:JSON.stringify(doc)}]};const agent=bindDesignSession({getSession:()=>session,parseDoc:JSON.parse,projectId:'p',getPolicy:()=>policy,getBuildInfo:()=>BUILD_INFO,buildAllSides:()=>copy(built),sideTransform:s=>transforms[s],validateDoc:()=>[]});const r=await agent.call('facade.generate',{expectedDocumentHash:await agent.documentHash(),style:'B'});assert.equal(r.result.projectBinding.designId,'100:0:1:base');session.current=1;assert.equal((await agent.call('facade.validate',{resultId:r.resultId})).fresh,false);});
test('studio binding follows live Editor.doc and project changes',async()=>{const editor={doc:copy(doc)};let project='first';const agent=bindStudioEditor({editor,getProjectId:()=>project,getPolicy:()=>policy,getBuildInfo:()=>BUILD_INFO,buildAllSides:()=>copy(built),sideTransform:s=>transforms[s],validateDoc:()=>[]});const r=await agent.call('facade.generate',{expectedDocumentHash:await agent.documentHash(),style:'C'});project='second';assert.equal((await agent.call('facade.validate',{resultId:r.resultId})).fresh,false);const ref=await agent.reference();assert.equal(ref.projectId,'second');assert.equal(ref.hashAlgorithm,'SHA-256/sorted-JSON-v1');});
test('comparison anchors come once from source geometry and cover three shots',()=>{const shots=closeupPlan(built,transforms);assert.deepEqual(shots.map(s=>s.shot),['stone','glass','entrance']);for(const s of shots){assert.equal(s.fov,34);assert.equal(s.width,960);assert.ok(s.position.every(Number.isFinite));}assert.deepEqual(shots,closeupPlan(built,transforms));});
